:root {
  /* Primary & Accent */
  --primary: #f59e0b;
  --primary-hover: #d97706;

  /* Background Palette - 明るく爽やかなベース */
  --bg-main: #fefdf8;
  --bg-card: #faf8f3;
  --bg-sidebar: #f5f1e8;

  /* Top Bar - 明るさを保ちながら視覚的な分離 */
  --top-bar-bg: #fffbf0;
  --top-bar-border: #f3e8d8;
  --top-bar-text: #1f2937;

  /* Text Colors */
  --text: #1f2937;
  --text-muted: #6b7280;

  /* Borders & Dividers */
  --border: #e5ddd0;
  --border-width: 1px;

  /* Typography */
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;

  /* Spacing & Sizing */
  --space-unit: 8px;
  --control-height: 40px;
  --radius-card: 12px;
  --radius-control: 8px;

  /* Shadows - 柔らかく明るい環境に合わせた浮遊感 */
  --shadow-card: 0 2px 8px rgba(31, 41, 55, 0.08), 0 1px 3px rgba(31, 41, 55, 0.04);

  /* Motion */
  --motion-duration: 200ms;

  /* Surface Texture - 明るく温かみのある紙のような質感 */
