function(container, apiUrl, tables) {
  // テーブルインデックスマッピング
  const tableIndexMap = {};
  tables.forEach((t, idx) => {
    tableIndexMap[t.tableName] = idx;
  });

  let currentProposalId = null;
  let currentProposalData = null;
  let allProposals = [];

  // ========== ユーティリティ関数 ==========
  function formatDate(dateStr) {
    if (!dateStr) return '--';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  }

  function getRiskLevelColor(level) {
    const colors = {
      '低': '#10b981',
      '中': '#f59e0b',
      '高': '#ef4444',
      '極高': '#7c2d12'
    };
    return colors[level] || '#6b7280';
  }

  function closeModal(modalId) {
    const modal = container.querySelector(`#${modalId}`);
    if (modal) modal.style.display = 'none';
  }

  function openModal(modalId) {
    const modal = container.querySelector(`#${modalId}`);
    if (modal) modal.style.display = 'flex';
  }

  // ========== 初期データ読込 ==========
  async function loadInitialData() {
    try {
      // 作業指示データ取得（最新の遅延リスクがある案件を取得）
      const workInstructions = await window.aivicApi.list(tableIndexMap['作業指示'] ?? 3);
      const progressData = await window.aivicApi.list(tableIndexMap['進捗データ'] ?? 8);
      const riskResults = await window.aivicApi.list(tableIndexMap['進捗遅延リスク判定結果'] ?? 9);
      const proficiencies = await window.aivicApi.list(tableIndexMap['作業者習熟度'] ?? 2);

      if (!workInstructions || workInstructions.length === 0) {
        container.querySelector('#progress-rate-value').textContent = '0';
        container.querySelector('#planned-progress').textContent = '0';
        return;
      }

      // 最新の作業指示を取得
      const latestWork = workInstructions[0];
      const latestProgress = progressData?.find(p => p.作業指示ID === latestWork.作業指示ID) || {};
      const latestRisk = riskResults?.find(r => r.作業指示ID === latestWork.作業指示ID) || {};

      // 進捗率表示
      const actualProgress = latestProgress.完了率 || latestWork.進捗率 || 0;
      const plannedProgress = Math.min(100, Math.floor((new Date() - new Date(latestWork.予定開始日時)) / (new Date(latestWork.予定終了日時) - new Date(latestWork.予定開始日時)) * 100));

      container.querySelector('#progress-rate-value').textContent = actualProgress;
      container.querySelector('#planned-progress').textContent = plannedProgress;
      container.querySelector('#progress-bar-actual').style.width = actualProgress + '%';
      container.querySelector('#planned-completion').textContent = formatDate(latestWork.予定終了日時);

      // リスク表示
      const riskLevel = latestRisk.リスクレベル || '低';
      const delayDays = latestRisk.遅延予測日数 || 0;
      container.querySelector('#risk-level').textContent = riskLevel;
      container.querySelector('#risk-level').style.background = getRiskLevelColor(riskLevel) + '20';
      container.querySelector('#risk-level').style.color = getRiskLevelColor(riskLevel);
      container.querySelector('#delay-days').textContent = delayDays;
      container.querySelector('#recommended-action').textContent = latestRisk.推奨対応 || '特に対応が必要ありません';

      // 生産性データ表示
      const productivityHtml = proficiencies?.slice(0, 5).map(p => `
        <div style="padding: 6px 0; border-bottom: 1px solid rgba(0,0,0,0.05);">
          <div style="font-weight: 500; color: var(--text);">${p.作業者ID?.substring(0, 8) || 'N/A'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">
            ${p.職務区分} / Lv${p.習熟度レベル || '-'}
          </div>
        </div>
      `).join('') || '<div style="color: var(--text-muted);">データなし</div>';
      container.querySelector('#productivity-list').innerHTML = productivityHtml;

      // 提案理由とロジック状況を設定
      container.querySelector('#proposal-reason').textContent = 
        `現在の進捗率 ${actualProgress}% に対し、計画進捗率は ${plannedProgress}% です。` +
        (delayDays > 0 ? `${delayDays}日の遅延が予測されるため、最適な人員配置を提案します。` : '予定通り進行中です。');

      container.querySelector('#logic-status').innerHTML = `
        <div style="margin-bottom: 6px;">✓ 習熟度レベル別難度調整: 有効</div>
        <div style="margin-bottom: 6px;">✓ 生産性データ連携: 有効</div>
        <div>✓ リスク判定ロジック: 有効</div>
      `;

    } catch (error) {
      console.error('初期データ読込エラー:', error);
    }
  }

  // ========== 配置案自動生成 ==========
  async function generateProposals() {
    try {
      const workInstructions = await window.aivicApi.list(tableIndexMap['作業指示'] ?? 3);
      const proficiencies = await window.aivicApi.list(tableIndexMap['作業者習熟度'] ?? 2);

      if (!workInstructions || workInstructions.length === 0) {
        alert('作業指示がありません');
        return;
      }

      const latestWork = workInstructions[0];
      const requiredPeople = latestWork.必要人数 || 3;

      // 3つの配置案を生成
      allProposals = [
        {
          id: 'proposal-a-' + Date.now(),
          name: '案A: 最小工数最適化',
          estimatedHours: Math.floor(requiredPeople * 8),
          estimatedCompletion: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
          status: '案',
          assignmentCount: requiredPeople,
          reason: '最小工数で完了を目指す配置。経験者を中心に配置。',
          assignments: proficiencies?.slice(0, requiredPeople).map((p, idx) => ({
            workerId: p.作業者ID,
            workerName: `作業者${idx + 1}`,
            proficiency: p.習熟度レベル || 3,
            plannedHours: 8,
            reason: `習熟度Lv${p.習熟度レベル || 3}で効率的に対応可能`
          })) || []
        },
        {
          id: 'proposal-b-' + Date.now(),
          name: '案B: 習熟度重視',
          estimatedHours: Math.floor(requiredPeople * 10),
          estimatedCompletion: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
          status: '案',
          assignmentCount: requiredPeople,
          reason: '習熟度の高い作業者を優先配置。品質と確実性を重視。',
          assignments: proficiencies?.slice(0, requiredPeople).map((p, idx) => ({
            workerId: p.作業者ID,
            workerName: `作業者${idx + 1}`,
            proficiency: p.習熟度レベル || 3,
            plannedHours: 10,
            reason: `高い習熟度で品質を確保`
          })) || []
        },
        {
          id: 'proposal-c-' + Date.now(),
          name: '案C: 人員平準化',
          estimatedHours: Math.floor(requiredPeople * 9),
          estimatedCompletion: new Date(Date.now() + 2.5 * 24 * 60 * 60 * 1000).toISOString(),
          status: '案',
          assignmentCount: requiredPeople,
          reason: '複数の習熟度レベルを組み合わせた平準配置。スキル育成も兼ねる。',
          assignments: proficiencies?.slice(0, requiredPeople).map((p, idx) => ({
            workerId: p.作業者ID,
            workerName: `作業者${idx + 1}`,
            proficiency: p.習熟度レベル || 3,
            plannedHours: 9,
            reason: `バランスの取れた配置で育成効果も期待`
          })) || []
        }
      ];

      renderProposals();
    } catch (error) {
      console.error('配置案生成エラー:', error);
      alert('配置案の生成に失敗しました');
    }
  }

  // ========== 配置案レンダリング ==========
  function renderProposals() {
    const container_el = container.querySelector('#proposals-container');
    container_el.innerHTML = allProposals.map(proposal => `
      <div class="card" data-proposal-id="${proposal.id}" style="background: var(--bg-card); padding: 14px; border-radius: 12px; box-shadow: var(--shadow-card); cursor: pointer; transition: all 0.2s ease; border: 2px solid transparent; background-image: var(--surface-texture); background-size: var(--surface-texture-size); background-position: var(--surface-texture-position);">
        <div style="font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 8px;">${proposal.name}</div>
        <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 6px;">
          <div>予想工数: <span style="color: var(--primary); font-weight: 600;">${proposal.estimatedHours}h</span></div>
          <div>予想完了: ${formatDate(proposal.estimatedCompletion)}</div>
          <div>割当人数: <span style="color: var(--primary); font-weight: 600;">${proposal.assignmentCount}名</span></div>
        </div>
        <div style="font-size: 11px; color: var(--text-muted); padding: 8px; background: rgba(245,158,11,0.05); border-radius: 6px; margin-top: 8px;">
          ${proposal.reason}
        </div>
      </div>
    `).join('');

    // クリックイベント登録
    container.querySelectorAll('[data-proposal-id]').forEach(el => {
      el.addEventListener('click', () => selectProposal(el.dataset.proposalId));
    });
  }

  // ========== 配置案選択 ==========
  function selectProposal(proposalId) {
    currentProposalId = proposalId;
    currentProposalData = allProposals.find(p => p.id === proposalId);

    // 選択状態を表示
    container.querySelectorAll('[data-proposal-id]').forEach(el => {
      if (el.dataset.proposalId === proposalId) {
        el.style.borderColor = 'var(--primary)';
        el.style.background = 'rgba(245,158,11,0.05)';
      } else {
        el.style.borderColor = 'transparent';
        el.style.background = 'var(--bg-card)';
      }
    });

    // 詳細表示
    renderProposalDetail();
    container.querySelector('#proposal-detail-container').style.display = 'block';

    // アクションボタン表示
    container.querySelector('#approve-btn').style.display = 'inline-block';
    container.querySelector('#reject-btn').style.display = 'inline-block';
    container.querySelector('#distribute-btn').style.display = 'inline-block';
  }

  // ========== 配置案詳細レンダリング ==========
  function renderProposalDetail() {
    if (!currentProposalData) return;

    const tbody = container.querySelector('#assignment-detail-tbody');
    tbody.innerHTML = currentProposalData.assignments.map(a => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text); border-right: 1px solid var(--border);">${a.workerId?.substring(0, 8) || 'N/A'}</td>
        <td style="padding: 8px; color: var(--text); border-right: 1px solid var(--border);">${a.workerName}</td>
        <td style="padding: 8px; text-align: center; color: var(--primary); font-weight: 600; border-right: 1px solid var(--border);">Lv${a.proficiency}</td>
        <td style="padding: 8px; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${a.plannedHours}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${a.reason}</td>
      </tr>
    `).join('');
  }

  // ========== 承認処理 ==========
  function showApproveModal() {
    if (!currentProposalData) return;
    const content = container.querySelector('#approve-modal-content');
    content.innerHTML = `
      <div><strong>${currentProposalData.name}</strong></div>
      <div style="margin-top: 8px;">予想工数: ${currentProposalData.estimatedHours}h</div>
      <div>割当人数: ${currentProposalData.assignmentCount}名</div>
      <div style="margin-top: 12px; color: var(--text);">この配置案を承認してもよろしいですか？</div>
    `;
    openModal('approve-modal-overlay');
  }

  async function approveProposal() {
    if (!currentProposalData) return;
    try {
      // 人員配置案テーブルに保存
      const proposalRecord = {
        配置案名: currentProposalData.name,
        拠点ID: 'site-001',
        チームID: 'team-001',
        作業指示ID: 'work-001',
        配置開始日: new Date().toISOString(),
        予想工数: currentProposalData.estimatedHours,
        予想完了日: currentProposalData.estimatedCompletion,
        ステータス: '承認待ち',
        説明: currentProposalData.reason
      };

      const saved = await window.aivicApi.save(tableIndexMap['人員配置案'] ?? 6, proposalRecord);
      if (saved) {
        closeModal('approve-modal-overlay');
        alert('配置案を承認しました');
        currentProposalData.status = '承認待ち';
      }
    } catch (error) {
      console.error('承認エラー:', error);
      alert('承認処理に失敗しました');
    }
  }

  // ========== 却下処理 ==========
  function showRejectModal() {
    openModal('reject-modal-overlay');
  }

  async function rejectProposal() {
    if (!currentProposalData) return;
    const reason = container.querySelector('#reject-reason').value;
    try {
      // 却下理由をログに記録（実装例）
      console.log(`配置案 ${currentProposalData.name} を却下: ${reason}`);
      closeModal('reject-modal-overlay');
      alert('配置案を却下しました');
      currentProposalData = null;
      currentProposalId = null;
      container.querySelector('#proposal-detail-container').style.display = 'none';
      container.querySelector('#approve-btn').style.display = 'none';
      container.querySelector('#reject-btn').style.display = 'none';
      container.querySelector('#distribute-btn').style.display = 'none';
    } catch (error) {
      console.error('却下エラー:', error);
      alert('却下処理に失敗しました');
    }
  }

  // ========== 配信処理 ==========
  function showDistributeModal() {
    if (!currentProposalData) return;
    const content = container.querySelector('#distribute-modal-content');
    content.innerHTML = `
      <div><strong>${currentProposalData.name}</strong></div>
      <div style="margin-top: 8px;">割当人数: ${currentProposalData.assignmentCount}名</div>
      <div style="margin-top: 12px; color: var(--text);">
        この配置案と作業指示を以下に一括配信します:
        <ul style="margin: 8px 0 0 16px;">
          <li>ハンディターミナル</li>
          <li>WMS (倉庫管理システム)</li>
          <li>作業者アプリ</li>
        </ul>
      </div>
    `;
    openModal('distribute-modal-overlay');
  }

  async function distributeProposal() {
    if (!currentProposalData) return;
    try {
      // 人員配置実行状況テーブルに登録
      const executionRecords = currentProposalData.assignments.map(a => ({
        人員配置案ID: currentProposalId,
        作業指示ID: 'work-001',
        作業者ID: a.workerId,
        拠点ID: 'site-001',
        チームID: 'team-001',
        配置状態: '計画中',
        計画開始日時: new Date().toISOString(),
        計画終了日時: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
        計画工数: a.plannedHours * 60
      }));

      for (const record of executionRecords) {
        await window.aivicApi.save(tableIndexMap['人員配置実行状況'] ?? 7, record);
      }

      // WMS連携ログ記録
      const wmsLog = {
        連携種別: '作業指示受信',
        連携方向: '送信',
        拠点_id: 'site-001',
        連携ステータス: '成功',
        連携開始日時: new Date().toISOString(),
        連携完了日時: new Date().toISOString(),
        処理件数: executionRecords.length,
        成功件数: executionRecords.length,
        失敗件数: 0
      };
      await window.aivicApi.save(tableIndexMap['WMS連携ログ'] ?? 11, wmsLog);

      closeModal('distribute-modal-overlay');
      alert('配置案と作業指示を一括配信しました');

      // 画面遷移
      setTimeout(() => {
        window.showScreen('scr-1789461813941');
      }, 1000);
    } catch (error) {
      console.error('配信エラー:', error);
      alert('配信処理に失敗しました');
    }
  }

  // ========== イベントリスナー登録 ==========
  container.querySelector('[data-testid="generate-proposals-btn"]').addEventListener('click', generateProposals);

  container.querySelector('[data-testid="approve-button"]').addEventListener('click', showApproveModal);
  container.querySelector('[data-testid="approve-modal-confirm"]').addEventListener('click', approveProposal);
  container.querySelector('[data-testid="approve-modal-cancel"]').addEventListener('click', () => closeModal('approve-modal-overlay'));

  container.querySelector('[data-testid="reject-button"]').addEventListener('click', showRejectModal);
  container.querySelector('[data-testid="reject-modal-confirm"]').addEventListener('click', rejectProposal);
  container.querySelector('[data-testid="reject-modal-cancel"]').addEventListener('click', () => closeModal('reject-modal-overlay'));

  container.querySelector('[data-testid="distribute-button"]').addEventListener('click', showDistributeModal);
  container.querySelector('[data-testid="distribute-modal-confirm"]').addEventListener('click', distributeProposal);
  container.querySelector('[data-testid="distribute-modal-cancel"]').addEventListener('click', () => closeModal('distribute-modal-overlay'));

  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    window.showScreen('scr-1789461783315');
  });

  // Esc キーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeModal('approve-modal-overlay');
      closeModal('reject-modal-overlay');
      closeModal('distribute-modal-overlay');
    }
  });

  // 初期データ読込
  loadInitialData();
}
